"""The ``pennywise`` command line."""

import argparse
import csv
import datetime
import io
import json
import re
import sys

from .ledger import ParseError, format_amount, format_entry, parse
from .report import balance, by_category, by_month, filter_entries

_CLI_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)


class _ReadError(Exception):
    """The ledger could not be read (exit 2)."""


def _date_arg(text):
    if _CLI_DATE_RE.fullmatch(text):
        try:
            return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money went from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def add_file(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")

    p = sub.add_parser("balance", help="print the total of all entries")
    add_file(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    add_file(p)
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    add_file(p)
    p.add_argument("--category", help="only this category (any case)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="first day, YYYY-MM-DD")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="last day, YYYY-MM-DD")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger file")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    add_file(p)
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_ledger(path):
    try:
        if path == "-":
            return sys.stdin.read()
        with open(path, "rb") as handle:
            return handle.read().decode("utf-8-sig")
    except (OSError, UnicodeDecodeError) as exc:
        raise _ReadError("cannot read %s: %s" % ("standard input" if path == "-" else path, exc))


def _sorted_entries(args, entries):
    chosen = filter_entries(entries, args.category, args.since, args.until)
    return sorted(chosen, key=lambda e: e.date)


def _out(text):
    sys.stdout.write(text + "\n")


def _cmd_balance(args, entries):
    total = format_amount(balance(entries))
    _out(json.dumps({"balance": total}) if args.json else total)


def _cmd_summary(args, entries):
    totals = (by_month if args.by == "month" else by_category)(entries)
    formatted = {name: format_amount(total) for name, total in sorted(totals.items())}
    if args.json:
        _out(json.dumps(formatted))
    else:
        for name, total in formatted.items():
            _out("%s  %s" % (name, total))


def _cmd_list(args, entries):
    chosen = _sorted_entries(args, entries)
    if args.json:
        _out(
            json.dumps(
                [
                    {
                        "date": e.date.isoformat(),
                        "category": e.category,
                        "amount": format_amount(e.amount),
                        "note": e.note,
                    }
                    for e in chosen
                ]
            )
        )
    else:
        for entry in chosen:
            _out(format_entry(entry))


def _cmd_export(args, entries):
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in sorted(entries, key=lambda e: e.date):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    sys.stdout.write(buffer.getvalue())


_READERS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def _cmd_add(args):
    """Validate and append one entry. Returns an exit status."""
    if args.file == "-":
        print("pennywise: add cannot write to standard input", file=sys.stderr)
        return 2
    note = args.note
    try:
        for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
            if not value or re.search(r"\s", value):
                raise ParseError(1, "invalid %s %r" % (name, value))
        if "\n" in note or "\r" in note:
            raise ParseError(1, "note must not contain a newline")
        entries = parse("%s %s %s %s" % (args.date, args.category, args.amount, note))
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    line = format_entry(entries[0])

    try:
        with open(args.file, "ab+") as handle:
            handle.seek(0, 2)
            prefix = b""
            if handle.tell() > 0:
                handle.seek(-1, 2)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
            handle.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        print("pennywise: cannot write %s: %s" % (args.file, exc), file=sys.stderr)
        return 2
    _out(line)
    return 0


def _run(args):
    if args.command == "add":
        return _cmd_add(args)
    try:
        text = _read_ledger(args.file)
    except _ReadError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    try:
        entries = parse(text)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    _READERS[args.command](args, entries)
    return 0


def main(argv=None):
    """Run the command line; returns the exit status."""
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    return _run(args)
